# Get values from the configuration file
led_status = config.get('game_led_status', 'off')
LED_PIN = int(config.get('game_led_pin', 0))
trigger = config.get('game_led_trigger', 'off')

# if led is on, then let there be light
if led_status == "on":
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT)
    led = GPIO.PWM(LED_PIN, 1000)  # Increase PWM frequency to 1000 Hz
    led.start(5)  # Start PWM with 5% duty cycle

# Define a global variable to control the LED thread
stop_thread = False

# make the leds a fancy
def led_trigger(trigger):
    global stop_thread
    if trigger == "on":
        led.ChangeDutyCycle(100)  # Set PWM to 100% duty cycle
    elif trigger == "off":
        led.ChangeDutyCycle(0)  # Set PWM to 0% duty cycle
    elif trigger == "blink":
        while not stop_thread:
            led.ChangeDutyCycle(100)
            time.sleep(0.5)
            led.ChangeDutyCycle(0)
            time.sleep(0.5)
    elif trigger == "heartbeat":
        while not stop_thread:
            led.ChangeDutyCycle(100)
            time.sleep(0.1)
            led.ChangeDutyCycle(0)
            time.sleep(0.1)
            led.ChangeDutyCycle(100)
            time.sleep(0.1)
            led.ChangeDutyCycle(0)
            time.sleep(0.7)
    elif trigger == "cpu":
        while not stop_thread:
            # Get the CPU usage
            cpu_usage = psutil.cpu_percent(interval=1)
            # Scale CPU usage (15% to 85%) to LED brightness (5% to 100%)
            if cpu_usage < 15:
                brightness = 5
            elif cpu_usage > 85:
                brightness = 100
            else:
                brightness = 5 + (cpu_usage - 15) / 70 * 95
            led.ChangeDutyCycle(brightness)
            time.sleep(1)

def clean_up_temp_file(temp_file):
    if os.path.exists(temp_file):
        os.remove(temp_file)

def generate_temp_script():

    temp_script_content = f"""#!/bin/bash
# A part of Amibian
# Copyright © 2025 Amibian.net
# All rights reserved
# Do not edit this file.

# change to working directory
cd {executable_dir}

# start program with specific configuration
./{executable_name} {arguments}

# After exit, change to home directory
cd ~

# clear screen on exit
clear
"""
    temp_script_path = os.path.join('/mnt/ram', 'temp_amibian_script.sh')
    with open(temp_script_path, 'w') as temp_script_file:
        temp_script_file.write(temp_script_content)
    os.chmod(temp_script_path, 0o755)
    return temp_script_path

def start_app():
    global stop_thread

    # make and run the temporary launcher
    temp_script_path = generate_temp_script()
    atexit.register(clean_up_temp_file, temp_script_path)

    # Start the LED fancyness in a separate thread if LED is turned on
    if led_status == "on":
        led_thread = threading.Thread(target=led_trigger, args=(trigger,))
        led_thread.start()

    # Run the temporary launcher
    app_process = subprocess.Popen([temp_script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    try:
        app_process.wait()
    except KeyboardInterrupt:
        pass
    finally:
        if led_status == "on":
            stop_thread = True
            led_thread.join()
            GPIO.output(LED_PIN, GPIO.LOW)
            GPIO.cleanup()
        clean_up_temp_file(temp_script_path)

if __name__ == "__main__":
    try:
        start_app()
    except Exception as e:
        print(f"Error: {{e}}")
