# Function to create the .desktop file
def create_desktop_file(desktop_file_path, script_path, icon_path, app_name):
    global last_desktop_file_path
    try:
        desktop_content = f'''[Desktop Entry]
Type=Application
Name={app_name}
Exec=python3 {script_path}
Icon={icon_path}
Terminal=false'''
        with open(desktop_file_path, 'w') as file:
            file.write(desktop_content)
        os.chmod(desktop_file_path, 0o755)
        last_desktop_file_path = desktop_file_path  # Store the path of the last created .desktop file
    except Exception as e:
        print(f"Error in create_desktop_file: {e}")

# GUI functions using Tkinter
def select_executable():
    file_path = filedialog.askopenfilename(initialdir=os.path.expanduser("~"))
    if file_path:  # Only insert if a file was selected
        executable_entry.delete(0, tk.END)  # Clear the entry field
        executable_entry.insert(0, file_path)  # Insert the new file path
        check_executable_name(file_path)  # Check the executable name

def select_icon():
    file_path = filedialog.askopenfilename(initialdir=os.path.expanduser("~"))
    if file_path:  # Only insert if a file was selected
        icon_entry.delete(0, tk.END)  # Clear the entry field
        icon_entry.insert(0, file_path)  # Insert the new file path

def select_uae_config():
    file_path = filedialog.askopenfilename(initialdir=os.path.expanduser("~"), filetypes=[("UAE Config Files", "*.uae")])
    if file_path:  # Only insert if a file was selected
        uae_config_entry.delete(0, tk.END)  # Clear the entry field
        uae_config_entry.insert(0, file_path)  # Insert the new file path
        update_additional_arguments(file_path)  # Update additional arguments

def update_additional_arguments(config_path):
    current_args = arguments_entry.get()
    new_args = f"-f {config_path}"
    arguments_entry.delete(0, tk.END)
    arguments_entry.insert(0, new_args)

def check_executable_name(file_path):
    executable_name = os.path.basename(file_path).lower()
    if "uae4arm" in executable_name or "amiberry" in executable_name:
        uae_config_label.grid(row=3, column=0, padx=10, pady=10)
        uae_config_entry.grid(row=3, column=1, padx=10, pady=10)
        uae_config_button.grid(row=3, column=2, padx=10, pady=10)
    else:
        uae_config_label.grid_remove()
        uae_config_entry.grid_remove()
        uae_config_button.grid_remove()

# Function to hide the UAE config option
def hide_uae_config_option():
    uae_config_label.grid_remove()
    uae_config_entry.grid_remove()
    uae_config_button.grid_remove()

# Function to create the launcher
def create_launcher():
    executable_path = executable_entry.get()
    launcher_name = launcher_name_entry.get()
    icon_path = icon_entry.get()
    arguments = arguments_entry.get()

    if not launcher_name:
        messagebox.showerror("Error", "Please enter a name for the launcher.")
        return

    amibian_folder = find_amibian_folder()
    new_script_path = os.path.join(amibian_folder, 'Pythons', 'launchers', f'{launcher_name}.py')
    desktop_file_path = os.path.join(os.path.expanduser("~"), 'Desktop', f'{launcher_name}.desktop')

    # Is the directory there?
    os.makedirs(os.path.dirname(new_script_path), exist_ok=True)

    # Check if the launcher name or .desktop file is already in use
    if os.path.exists(new_script_path) or os.path.exists(desktop_file_path):
        messagebox.showerror("Error", "The launcher name or .desktop file is already in use. Please choose a different name.")
    else:
        try:
            create_launcher_script(new_script_path, executable_path, arguments)
            create_desktop_file(desktop_file_path, new_script_path, icon_path, launcher_name)
            messagebox.showinfo("Success", "Launcher created successfully!")
            clear_fields()  # Clear input fields after creating the launcher
            hide_uae_config_option()  # Hide the UAE config option
        except Exception as e:
            print(f"Error in create_launcher: {e}")
            traceback.print_exc()  # Print full traceback
            messagebox.showerror("Error", f"An error occurred: {e}")

# Function to clear input fields
def clear_fields():
    executable_entry.delete(0, tk.END)
    launcher_name_entry.delete(0, tk.END)
    icon_entry.delete(0, tk.END)
    arguments_entry.delete(0, tk.END)
    uae_config_entry.delete(0, tk.END)  # Clear the UAE config entry
    hide_uae_config_option()  # Hide the UAE config option

# Function to locate the image file
def get_image_path():
    script_dir = get_script_dir()
    return os.path.join(script_dir, '..', 'graphics', 'amibian_logo', 'Amibian.png')

# Function to cancel the last creation
def cancel_last_creation():
    global last_script_path, last_desktop_file_path
    if last_script_path or last_desktop_file_path:
        if messagebox.askyesno("Confirm Cancel", "Are you sure you want to delete the last created files?"):
            if last_script_path and os.path.exists(last_script_path):
                os.remove(last_script_path)
                last_script_path = None
            if last_desktop_file_path and os.path.exists(last_desktop_file_path):
                os.remove(last_desktop_file_path)
                last_desktop_file_path = None
            messagebox.showinfo("Cancelled", "Last created files have been deleted.")
            clear_fields()  # Clear input fields after cancellation
        else:
            messagebox.showinfo("Nothing to cancel", "Nothing has been done yet. Relax, you're good!")
    else:
        messagebox.showinfo("Nothing to cancel", "Nothing has been done yet. Relax, you're good!")

